WITH kept_keys AS (SELECT channel FROM promotions EXCEPT SELECT channel FROM promotions WHERE channel = 'partner'), reconciled AS (SELECT s.* FROM promotions s INNER JOIN kept_keys k ON s.channel = k.channel) SELECT id, channel, promo_code, ends_on, discount_pct, CASE WHEN promo_code RLIKE '^(SPRING10|WELCOME5)$' THEN 'PRIORITY' ELSE 'GROUP_B' END AS promo_code_zone FROM reconciled
